      expect(denied).toMatchObject({
        requiredPermission: AuthSourceControlWriteScope,
        requiredScope: AuthOrchestrationOperateScope,
      });
      const { permissions: _exact, ...legacy } = grant(true);
      registry.set(sessions(env), AsyncResult.success(legacy));
      expect(registry.get(git.permissionAtom(env))).toBe(true);
      yield* git.authorize(registry, env);
    }),
  ),
);

it.effect("rejects protected unary and streamed RPCs outside a guarded command", () =>
  Effect.gen(function* () {
    let writes = 0;
    const session = {
      client: {
        [WS_METHODS.scheduledTasksDelete]: () =>
          Effect.sync(() => {
            writes++;
            return { id: ScheduledTaskId.make("task") };
          }),
        [WS_METHODS.gitRunStackedAction]: () =>
          Stream.fromEffect(
            Effect.sync(() => {
              writes++;
            }),
          ),
      },
    } as unknown as RpcSession;
    const supervisor = {
      target: { environmentId: env, label: "target" },
      session: yield* SubscriptionRef.make(Option.some(session)),
    } as unknown as EnvironmentSupervisor["Service"];
    const unary = yield* requestGuarded(WS_METHODS.scheduledTasksDelete, {
      id: ScheduledTaskId.make("task"),
    }).pipe(Effect.provideService(EnvironmentSupervisor, supervisor), Effect.flip);
    expect(unary._tag).toBe("EnvironmentAuthorizationError");
    const streamed = yield* runStreamGuarded(WS_METHODS.gitRunStackedAction, {
      actionId: "test-action",
      cwd: "/repo",
      action: "commit",
    }).pipe(Stream.runDrain, Effect.provideService(EnvironmentSupervisor, supervisor), Effect.flip);
    expect(streamed._tag).toBe("EnvironmentAuthorizationError");
    expect(writes).toBe(0);
  }),
);

import { WS_METHODS, type EnvironmentId } from "@t3tools/contracts";
import * as Cause from "effect/Cause";
import * as Effect from "effect/Effect";
import * as Equal from "effect/Equal";
import * as Exit from "effect/Exit";
import * as Fiber from "effect/Fiber";
import * as HashMap from "effect/HashMap";
import * as Option from "effect/Option";
import * as Stream from "effect/Stream";
import * as SubscriptionRef from "effect/SubscriptionRef";
import { AsyncResult, Atom } from "effect/reactivity";
import {
  attentionSyncFailed,
  emptyAttentionSync,
  reduceAttentionStream,
} from "../attentionSync.ts";
import type { ConnectionCatalogEntry } from "../connection/catalog.ts";
import type { SupervisorConnectionState } from "../connection/model.ts";
import { EnvironmentRegistry } from "../connection/registry.ts";
import { EnvironmentSupervisor } from "../connection/supervisor.ts";
import { EnvironmentRpcSubscriptionObserver, isRpcClientError } from "../rpc/client.ts";
import type { RpcSession } from "../rpc/session.ts";
import { projectAttentionNotifications } from "./attentionNotifications.ts";
import {
  aggregateAttention,
  emptyEnvironmentAttention,
  type AttentionWorkspaceState,
  type EnvironmentAttentionState,
} from "./attentionProjection.ts";

function authorizationLost(state: SupervisorConnectionState) {
  return (
    state.phase === "blocked" &&
    (state.lastFailure?.reason === "authentication" || state.lastFailure?.reason === "permission")
  );
}

/** Owns only a subscription; connection lifecycle belongs to the existing supervisor. */
const makeEnvironmentAttentionState = Effect.fn("makeEnvironmentAttentionState")(function* () {
  const supervisor = yield* EnvironmentSupervisor;
  const observer = yield* EnvironmentRpcSubscriptionObserver;
  const environmentId = supervisor.target.environmentId;
  const state = yield* SubscriptionRef.make(emptyEnvironmentAttention());
  let sync = emptyAttentionSync();

  const clear = Effect.fn(function* (
    status: "unauthorized" | "unsupported" | "error",
    reason: string,
  ) {
    sync = emptyAttentionSync();
    yield* SubscriptionRef.set(state, { ...emptyEnvironmentAttention(), status, reason });
  });
  const markStale = (reason: string) =>
    SubscriptionRef.update(state, (current): EnvironmentAttentionState => ({
      ...current,
      status:
        current.status === "unauthorized"
          ? "unauthorized"
          : current.hasSnapshot
            ? "stale"
            : "loading",
      reason: current.status === "unauthorized" ? "unauthorized" : reason,
      notificationCandidates: HashMap.empty(),
    }));
  const ownsSession = Effect.fn(function* (session: RpcSession) {
    const active = yield* SubscriptionRef.get(supervisor.session);
    return (
      Option.isSome(active) &&
      active.value === session &&
      !authorizationLost(yield* SubscriptionRef.get(supervisor.state))
    );
  });

  const consume = Effect.fn("attention.consumeSession")(function* (session: RpcSession) {
    // The delivery token binds server-side authentication, not just environment ID.
    // A replacement RPC session must establish a fresh fence before reusing authority.
    sync = emptyAttentionSync();
    yield* SubscriptionRef.update(state, (current): EnvironmentAttentionState => ({
      ...current,
      status: current.hasSnapshot ? "syncing" : "loading",
      reason: null,
      notificationCandidates: HashMap.empty(),
    }));
    const config = yield* Effect.exit(session.initialConfig);
    if (!(yield* ownsSession(session))) return;
    if (Exit.isFailure(config)) {
      if (Cause.hasInterrupts(config.cause)) return yield* Effect.interrupt;
      if (
        config.cause.reasons.some(
          (reason) =>
            reason._tag === "Fail" &&
            reason.error._tag === "ConnectionBlockedError" &&
            (reason.error.reason === "authentication" || reason.error.reason === "permission"),
        )
      ) {
        yield* clear("unauthorized", "unauthorized");
      } else {
        yield* markStale("configuration-unavailable");
      }
      yield* Effect.logWarning("Attention configuration unavailable.", { environmentId });
      return;
    }
    if (config.value.environment.environmentId !== environmentId) {
      yield* clear("error", "environment-mismatch");
      yield* Effect.logWarning("Attention configuration environment mismatch.", {
        environmentId,
      });
      return;
    }
    if (config.value.environment.capabilities.attentionSync !== true) {
      yield* clear("unsupported", "attention-sync-unsupported");
      return;
    }

    let failures = 0;
    while (yield* ownsSession(session)) {
      let retry = false;
      let terminal = false;
      const input = sync.cursor !== null && sync.status === "stale" ? { cursor: sync.cursor } : {};
      const completeObservation = yield* observer.observe({
        environmentId,
        method: WS_METHODS.attentionSubscribe,
        input,
      });
      // oxlint-disable-next-line t3code/no-rpc-permission-bypass -- This owned read-only stream must stay on the exact authenticated session; the observer and server scope checks still apply.
      const result = yield* session.client[WS_METHODS.attentionSubscribe](input).pipe(
        Stream.tap((message) =>
          Effect.gen(function* () {
            if (retry || terminal) return;
            if (!(yield* ownsSession(session))) {
              terminal = true;
              return;
            }
            if (message.type !== "reset-required" && message.environmentId !== environmentId) {
              yield* clear("error", "environment-mismatch");
              yield* Effect.logWarning("Attention stream environment mismatch.", {
                environmentId,
              });
              terminal = true;
              return;
            }
            const before = sync;
            sync = reduceAttentionStream(sync, message);
            if (sync.status === "reset-required") {
              retry = message.type === "reset-required" && message.reason !== "message-too-large";
              terminal = !retry;
              yield* SubscriptionRef.update(state, (current): EnvironmentAttentionState => ({
                ...current,
                status: retry ? (current.hasSnapshot ? "stale" : "loading") : "error",
                reason: sync.reason,
                notificationCandidates: HashMap.empty(),
              }));
              yield* Effect.logWarning("Attention stream requires resynchronization.", {
                environmentId,
                reason: sync.reason,
                retry,
              });
            } else if (sync.status === "live") {
              yield* SubscriptionRef.update(state, (current): EnvironmentAttentionState => ({
                status: "live",
                hasSnapshot: true,
                entries: sync.entries,
                reason: null,
                notificationCandidates: projectAttentionNotifications(
                  current.notificationCandidates ?? HashMap.empty(),
                  before,
                  sync,
                  message,
                ),
              }));
            } else if (message.type === "begin") {
              yield* SubscriptionRef.update(state, (current): EnvironmentAttentionState => ({
                ...current,
                status: current.hasSnapshot ? "syncing" : "loading",
                reason: null,
                notificationCandidates: HashMap.empty(),
              }));
            }
          }),
        ),
        Stream.takeUntil(() => retry || terminal),
        Stream.runDrain,
        Effect.ensuring(completeObservation),
        Effect.exit,
      );
      if (!(yield* ownsSession(session))) return;
      if (Exit.isFailure(result)) {
        if (Cause.hasInterrupts(result.cause)) return yield* Effect.interrupt;
        const failuresOnly = result.cause.reasons.filter((reason) => reason._tag === "Fail");
        const expected = failuresOnly.length === result.cause.reasons.length;
        const unauthorized = failuresOnly.some(
          (reason) => reason.error._tag === "EnvironmentAuthorizationError",
        );
        if (unauthorized) {
          yield* clear("unauthorized", "unauthorized");
          yield* Effect.logWarning("Attention access revoked.", { environmentId });
          return;
        }
        const transport =
          expected &&
          failuresOnly.length > 0 &&
          failuresOnly.every((reason) => isRpcClientError(reason.error));
        const unavailable =
          expected &&
          failuresOnly.length > 0 &&
          failuresOnly.every(
            (reason) =>
              reason.error._tag === "AttentionSyncError" && reason.error.reason === "unavailable",
          );
        sync = attentionSyncFailed(sync, "disconnected");
        yield* Effect.logWarning("Attention subscription failed.", {
          environmentId,
          transport,
          unavailable,
        });
        if (transport) {
          yield* markStale("transport-unavailable");
          return;
        }
        if (!unavailable) {
          yield* SubscriptionRef.update(state, (current): EnvironmentAttentionState => ({
            ...current,
            status: "error",
            reason: "attention-protocol-error",
          }));
          return;
        }
        yield* markStale("attention-unavailable");
      } else if (terminal) {
        return;
      } else if (!retry) {
        sync = attentionSyncFailed(sync, "disconnected");
        yield* markStale("stream-ended");
        yield* Effect.logWarning("Attention subscription ended before its connection.", {
          environmentId,
        });
      }
      yield* Effect.sleep([3_000, 4_000, 8_000, 16_000][Math.min(failures++, 3)]!);
    }
  });

  yield* Stream.merge(
    SubscriptionRef.changes(supervisor.session),
    SubscriptionRef.changes(supervisor.state),
  ).pipe(
    Stream.mapEffect(() =>
      Effect.gen(function* () {
        const session = yield* SubscriptionRef.get(supervisor.session);
        const unauthorized = authorizationLost(yield* SubscriptionRef.get(supervisor.state));
        return { session: Option.getOrNull(session), unauthorized };
      }),
    ),
    Stream.changesWith(
      (left, right) => left.session === right.session && left.unauthorized === right.unauthorized,
    ),
    Stream.switchMap(({ session, unauthorized }) =>
      Stream.fromEffect(
        unauthorized
          ? clear("unauthorized", "unauthorized")
          : session !== null
            ? consume(session)
            : Effect.gen(function* () {
                sync = attentionSyncFailed(sync, "disconnected");
                yield* markStale("disconnected");
              }),
      ),
    ),
    Stream.runDrain,
    Effect.forkScoped,
  );
  return state;
});

const EMPTY_WORKSPACE: AttentionWorkspaceState = { isReady: false, environments: new Map() };

export const makeAttentionWorkspaceState = Effect.fn("makeAttentionWorkspaceState")(function* () {
  const registry = yield* EnvironmentRegistry;
  const state = yield* SubscriptionRef.make(EMPTY_WORKSPACE);
  const workers = new Map<
    EnvironmentId,
    {
      entry: ConnectionCatalogEntry;
      fiber?: Fiber.Fiber<void, never>;
    }
  >();
  yield* SubscriptionRef.changes(registry.entries).pipe(
    Stream.runForEach((entries) =>
      Effect.gen(function* () {
        const retired = [...workers].filter(
          ([id, worker]) =>
            !entries.get(id)?.enabled || !Equal.equals(entries.get(id), worker.entry),
        );
        for (const [id] of retired) workers.delete(id);
        yield* SubscriptionRef.update(state, (current) => ({
          isReady: true,
          environments: new Map(
            [...entries]
              .filter(([, entry]) => entry.enabled)
              .map(([id]) => [
                id,
                workers.has(id)
                  ? (current.environments.get(id) ?? emptyEnvironmentAttention())
                  : emptyEnvironmentAttention(),
              ]),
          ),
        }));
        yield* Effect.forEach(
          retired,
          ([, worker]) =>
            worker.fiber === undefined ? Effect.void : Fiber.interrupt(worker.fiber),
          {
            discard: true,
          },
        );
        for (const [id, entry] of entries) {
          if (!entry.enabled || workers.has(id)) continue;
          const worker: { entry: ConnectionCatalogEntry; fiber?: Fiber.Fiber<void, never> } = {
            entry,
          };
          workers.set(id, worker);
          worker.fiber = yield* registry
            .runStream(
              id,
              Stream.unwrap(
                makeEnvironmentAttentionState().pipe(Effect.map(SubscriptionRef.changes)),
              ),
            )
            .pipe(
              Stream.runForEach((value) =>
                SubscriptionRef.update(state, (current) => {
                  if (workers.get(id) !== worker) return current;
                  const environments = new Map(current.environments);
                  environments.set(id, value);
                  return { ...current, environments };
                }),
              ),
              Effect.catchTags({
                EnvironmentNotRegisteredError: Effect.fn("attention.environmentUnavailable")(
                  function* () {
                    if (!(yield* SubscriptionRef.get(registry.entries)).get(id)?.enabled) return;
                    yield* Effect.logWarning("Attention environment is no longer registered.", {
                      environmentId: id,
                    });
                    yield* SubscriptionRef.update(state, (current) => {
                      if (workers.get(id) !== worker) return current;
                      const environments = new Map(current.environments);
                      environments.set(id, {
                        ...emptyEnvironmentAttention(),
                        status: "error",
                        reason: "environment-unavailable",
                      });
                      return { ...current, environments };
                    });
                  },
                ),
              }),
              Effect.forkScoped,
            );
        }
      }),
    ),
    Effect.forkScoped,
  );
  return state;
});

/** One shared workspace atom owns all enabled-environment subscriptions for its consumers. */
export function createAttentionWorkspaceAtoms<R, E>(
  runtime: Atom.AtomRuntime<EnvironmentRegistry | R, E>,
) {
  const stateAtom = runtime.atom(
    Stream.unwrap(makeAttentionWorkspaceState().pipe(Effect.map(SubscriptionRef.changes))),
    { initialValue: EMPTY_WORKSPACE },
  );
  const valueAtom = Atom.make((get) =>
    Option.getOrElse(AsyncResult.value(get(stateAtom)), () => EMPTY_WORKSPACE),
  ).pipe(Atom.withLabel("attention-workspace"));
  const aggregateAtom = Atom.make((get) => aggregateAttention(get(valueAtom))).pipe(
    Atom.withLabel("attention-aggregate"),
  );
  return { stateAtom, valueAtom, aggregateAtom };
}

export * from "./attentionProjection.ts";

import * as Effect from "effect/Effect";
import * as Schema from "effect/Schema";

const TWS_SUPPORTED_CLI_VERSION = "v1.2.14";
const TWS_SUPPORTED_REPORT_SCHEMA_VERSION = 1;

export const TwsCommandKind = Schema.Literals([
  "version",
  "registry-list",
  "registry-check",
  "status",
  "stack-status",
]);
export type TwsCommandKind = typeof TwsCommandKind.Type;

const TwsCommandOutputStream = Schema.Literals(["stdout", "stderr"]);

export const TwsCommandFailureLine = Schema.Struct({
  message: Schema.String,
  streams: Schema.Array(TwsCommandOutputStream),
});
export type TwsCommandFailureLine = typeof TwsCommandFailureLine.Type;

export class TwsCommandFailedError extends Schema.TaggedError<TwsCommandFailedError>()(
  "TwsCommandFailedError",
  {
    command: TwsCommandKind,
    exitCode: Schema.NullOr(Schema.Number),
    failures: Schema.Array(TwsCommandFailureLine),
  },
) {
  override get message(): string {
    return `TWS ${this.command} failed with exit status ${this.exitCode ?? "unknown"}`;
  }
}

export class TwsMalformedVersionError extends Schema.TaggedError<TwsMalformedVersionError>()(
  "TwsMalformedVersionError",
  {
    detail: Schema.String,
  },
) {
  override get message(): string {
    return this.detail;
  }
}

export class TwsUnsupportedVersionError extends Schema.TaggedError<TwsUnsupportedVersionError>()(
  "TwsUnsupportedVersionError",
  {
    actualVersion: Schema.String,
    supportedVersion: Schema.String,
  },
) {
  override get message(): string {
    return `Unsupported TWS version ${this.actualVersion}; expected ${this.supportedVersion}`;
  }
}

export class TwsInvalidFeatureError extends Schema.TaggedError<TwsInvalidFeatureError>()(
  "TwsInvalidFeatureError",
  {
    detail: Schema.String,
  },
) {
  override get message(): string {
    return this.detail;
  }
}

export const TwsOutputDecodeReason = Schema.Literals([
  "invalid-json",
  "invalid-shape",
  "missing-required-keys",
  "invalid-utf8",
]);
export type TwsOutputDecodeReason = typeof TwsOutputDecodeReason.Type;

export class TwsOutputDecodeError extends Schema.TaggedError<TwsOutputDecodeError>()(
  "TwsOutputDecodeError",
  {
    command: TwsCommandKind,
    reason: TwsOutputDecodeReason,
    detail: Schema.String,
  },
) {
  override get message(): string {
    return `Could not decode TWS ${this.command} output: ${this.detail}`;
  }
}

export class TwsUnsupportedSchemaVersionError extends Schema.TaggedError<TwsUnsupportedSchemaVersionError>()(
  "TwsUnsupportedSchemaVersionError",
  {
    command: Schema.Literals(["status", "stack-status"]),
    actualVersion: Schema.Unknown,
    supportedVersion: Schema.Number,
  },
) {
  override get message(): string {
    return `Unsupported TWS ${this.command} schema version`;
  }
}

export const TwsCliDecodeError = Schema.Union([
  TwsCommandFailedError,
  TwsMalformedVersionError,
  TwsUnsupportedVersionError,
  TwsInvalidFeatureError,
  TwsOutputDecodeError,
  TwsUnsupportedSchemaVersionError,
]);
export type TwsCliDecodeError = typeof TwsCliDecodeError.Type;

type RawObject = Readonly<Record<string, unknown>>;

export interface TwsVersionInfo {
  readonly version: typeof TWS_SUPPORTED_CLI_VERSION;
}

export interface TwsRegistryEntry {
  readonly id: string;
  readonly path: string;
  readonly aliases: ReadonlyArray<string>;
  readonly kind: string;
  readonly gitIdentity: string;
  readonly markerId: string;
  readonly addedAt: string;
  readonly updatedAt: string;
  readonly raw: RawObject;
}

export interface TwsRegistryCheck {
  readonly entry: TwsRegistryEntry;
  readonly status: string;
  readonly raw: RawObject;
}

export interface TwsUnknownEnumObservation {
  readonly path: string;
  readonly raw: string;
  readonly normalized: "unknown";
}

interface TwsDecodedReportBase {
  readonly schemaVersion: 1;
  readonly raw: RawObject;
  readonly unknownEnums: ReadonlyArray<TwsUnknownEnumObservation>;
  readonly decoderDegraded: boolean;
  readonly twsNeedsAttention: boolean;
}

export interface TwsStatusReport extends TwsDecodedReportBase {
  readonly generatedAt: string;
  readonly workspace: RawObject;
  readonly features: ReadonlyArray<unknown>;
  readonly issues: ReadonlyArray<unknown>;
  readonly summary: RawObject;
}

export interface TwsStackStatusReport extends TwsDecodedReportBase {
  readonly workspace: RawObject;
  readonly feature: string;
  readonly entries: ReadonlyArray<unknown>;
  readonly summary: RawObject;
}

const RawObjectSchema = Schema.Record(Schema.String, Schema.Unknown);
const decodeJson = Schema.decodeUnknownEffect(Schema.fromJsonString(Schema.Unknown));
const decodeRawObject = Schema.decodeUnknownEffect(RawObjectSchema);

const RegistryEntryWire = Schema.Struct({
  id: Schema.String,
  path: Schema.String,
  aliases: Schema.Array(Schema.String),
  kind: Schema.String,
  git_identity: Schema.String,
  marker_id: Schema.String,
  added_at: Schema.String,
  updated_at: Schema.String,
});
const decodeRegistryEntryWire = Schema.decodeUnknownEffect(RegistryEntryWire);

const RegistryCheckWire = Schema.Struct({
  entry: Schema.Unknown,
  status: Schema.String,
});
const decodeRegistryCheckWire = Schema.decodeUnknownEffect(RegistryCheckWire);

const STATUS_REQUIRED_KEYS = [
  "schema_version",
  "generated_at",
  "workspace",
  "features",
  "issues",
  "summary",
] as const;
const STACK_REQUIRED_KEYS = [
  "schema_version",
  "workspace",
  "feature",
  "entries",
  "summary",
] as const;

const KNOWN_RUNTIME_PRESENCE = new Set(["present", "absent", "stale", "unknown"]);
const KNOWN_AGENT_STATE = new Set(["working", "ready", "blocked", "done", "unknown"]);
const KNOWN_ATTENTION_STATUS = new Set(["needs_attention", "active", "idle"]);

function outputDecodeError(
  command: TwsCommandKind,
  reason: TwsOutputDecodeReason,
  detail: string,
): TwsOutputDecodeError {
  return new TwsOutputDecodeError({ command, reason, detail });
}

function decodeJsonValue(
  command: TwsCommandKind,
  output: string,
): Effect.Effect<unknown, TwsOutputDecodeError> {
  return decodeJson(output).pipe(
    Effect.mapError(() => outputDecodeError(command, "invalid-json", "invalid JSON")),
  );
}

function rawObject(
  command: TwsCommandKind,
  value: unknown,
  detail: string,
): Effect.Effect<RawObject, TwsOutputDecodeError> {
  return decodeRawObject(value).pipe(
    Effect.mapError(() => outputDecodeError(command, "invalid-shape", detail)),
  );
}

function missingRequiredKeys(
  raw: RawObject,
  required: ReadonlyArray<string>,
): ReadonlyArray<string> {
  return required.filter((key) => !Object.hasOwn(raw, key));
}

function canonicalErrorLine(line: string): string {
  const trimmed = line.trim();
  return trimmed.replace(/^error:\s*/iu, "").trim();
}

export function twsCommandFailureLines(
  stdout: string,
  stderr: string,
  exitCode: number | null,
): ReadonlyArray<TwsCommandFailureLine> {
  const failures = new Map<
    string,
    { readonly message: string; readonly streams: Set<"stdout" | "stderr"> }
  >();

  for (const [stream, output] of [
    ["stdout", stdout],
    ["stderr", stderr],
  ] as const) {
    for (const line of output.split(/\r?\n/u)) {
      const message = canonicalErrorLine(line);
      if (!message) {
        continue;
      }
      const key = message.toLowerCase();
      const existing = failures.get(key);
      if (existing) {
        existing.streams.add(stream);
      } else {
        failures.set(key, { message, streams: new Set([stream]) });
      }
    }
  }

  if (failures.size === 0) {
    return [
      {
        message: `tws exited with status ${exitCode ?? "unknown"}`,
        streams: [],
      },
    ];
  }

  return [...failures.values()].map((failure) => ({
    message: failure.message,
    streams: [...failure.streams].sort(),
  }));
}

export function decodeTwsVersionOutput(
  output: string,
): Effect.Effect<TwsVersionInfo, TwsMalformedVersionError | TwsUnsupportedVersionError> {
  const match = /^tws version (v\d+\.\d+\.\d+)$/u.exec(output.trim());
  if (!match?.[1]) {
    return Effect.fail(
      new TwsMalformedVersionError({
        detail: "TWS version output did not match 'tws version vX.Y.Z'",
      }),
    );
  }
  if (match[1] !== TWS_SUPPORTED_CLI_VERSION) {
    return Effect.fail(
      new TwsUnsupportedVersionError({
        actualVersion: match[1],
        supportedVersion: TWS_SUPPORTED_CLI_VERSION,
      }),
    );
  }
  return Effect.succeed({ version: TWS_SUPPORTED_CLI_VERSION });
}

function decodeRegistryEntry(
  command: "registry-list" | "registry-check",
  value: unknown,
): Effect.Effect<TwsRegistryEntry, TwsOutputDecodeError> {
  return Effect.all({
    raw: rawObject(command, value, "registry entry must be an object"),
    entry: decodeRegistryEntryWire(value).pipe(
      Effect.mapError(() =>
        outputDecodeError(command, "invalid-shape", "registry entry fields are invalid"),
      ),
    ),
  }).pipe(
    Effect.map(({ raw, entry }) => ({
      id: entry.id,
      path: entry.path,
      aliases: entry.aliases,
      kind: entry.kind,
      gitIdentity: entry.git_identity,
      markerId: entry.marker_id,
      addedAt: entry.added_at,
      updatedAt: entry.updated_at,
      raw,
    })),
  );
}

export function decodeTwsRegistryList(
  output: string,
): Effect.Effect<ReadonlyArray<TwsRegistryEntry>, TwsOutputDecodeError> {
  return decodeJsonValue("registry-list", output).pipe(
    Effect.flatMap((value) =>
      Array.isArray(value)
        ? Effect.forEach(value, (entry) => decodeRegistryEntry("registry-list", entry), {
            concurrency: 1,
          })
        : Effect.fail(
            outputDecodeError("registry-list", "invalid-shape", "registry list must be an array"),
          ),
    ),
  );
}

export function decodeTwsRegistryCheck(
  output: string,
): Effect.Effect<ReadonlyArray<TwsRegistryCheck>, TwsOutputDecodeError> {
  return decodeJsonValue("registry-check", output).pipe(
    Effect.flatMap((value) =>
      Array.isArray(value)
        ? Effect.forEach(
            value,
            (item) =>
              Effect.all({
                raw: rawObject("registry-check", item, "registry check item must be an object"),
                item: decodeRegistryCheckWire(item).pipe(
                  Effect.mapError(() =>
                    outputDecodeError(
                      "registry-check",
                      "invalid-shape",
                      "registry check fields are invalid",
                    ),
                  ),
                ),
              }).pipe(
                Effect.flatMap(({ raw, item: decoded }) =>
                  decodeRegistryEntry("registry-check", decoded.entry).pipe(
                    Effect.map((entry) => ({
                      entry,
                      status: decoded.status,
                      raw,
                    })),
                  ),
                ),
              ),
            { concurrency: 1 },
          )
        : Effect.fail(
            outputDecodeError("registry-check", "invalid-shape", "registry check must be an array"),
          ),
    ),
  );
}

function observeUnknownEnums(
  value: unknown,
  path: ReadonlyArray<string> = [],
): ReadonlyArray<TwsUnknownEnumObservation> {
  if (Array.isArray(value)) {
    return value.flatMap((entry, index) => observeUnknownEnums(entry, [...path, String(index)]));
  }
  if (typeof value !== "object" || value === null) {
    return [];
  }

  const raw = value as RawObject;
  const observations: TwsUnknownEnumObservation[] = [];
  const runtimePresence = raw.runtime_presence;
  if (typeof runtimePresence === "string" && !KNOWN_RUNTIME_PRESENCE.has(runtimePresence)) {
    observations.push({
      path: [...path, "runtime_presence"].join("."),
      raw: runtimePresence,
      normalized: "unknown",
    });
  }
  const agentState = raw.agent_state;
  if (typeof agentState === "string" && !KNOWN_AGENT_STATE.has(agentState)) {
    observations.push({
      path: [...path, "agent_state"].join("."),
      raw: agentState,
      normalized: "unknown",
    });
  }
  const attention = raw.attention;
  if (typeof attention === "object" && attention !== null && !Array.isArray(attention)) {
    const attentionStatus = (attention as RawObject).status;
    if (typeof attentionStatus === "string" && !KNOWN_ATTENTION_STATUS.has(attentionStatus)) {
      observations.push({
        path: [...path, "attention", "status"].join("."),
        raw: attentionStatus,
        normalized: "unknown",
      });
    }
  }

  for (const [key, nested] of Object.entries(raw)) {
    observations.push(...observeUnknownEnums(nested, [...path, key]));
  }
  return observations;
}

function hasTwsAttention(value: unknown): boolean {
  if (Array.isArray(value)) {
    return value.some(hasTwsAttention);
  }
  if (typeof value !== "object" || value === null) {
    return false;
  }
  const raw = value as RawObject;
  const attention = raw.attention;
  if (
    typeof attention === "object" &&
    attention !== null &&
    !Array.isArray(attention) &&
    (attention as RawObject).status === "needs_attention"
  ) {
    return true;
  }
  return Object.values(raw).some(hasTwsAttention);
}

const decodeVersionedReport = Effect.fn("TwsCliDecoder.decodeVersionedReport")(function* (
  command: "status" | "stack-status",
  output: string,
  requiredKeys: ReadonlyArray<string>,
): Effect.fn.Return<RawObject, TwsOutputDecodeError | TwsUnsupportedSchemaVersionError> {
  const value = yield* decodeJsonValue(command, output);
  const raw = yield* rawObject(command, value, "report must be an object");
  const missing = missingRequiredKeys(raw, requiredKeys);
  if (missing.length > 0) {
    return yield* outputDecodeError(
      command,
      "missing-required-keys",
      `missing required keys: ${missing.join(", ")}`,
    );
  }
  const schemaVersion = raw.schema_version;
  if (
    typeof schemaVersion !== "number" ||
    !Number.isInteger(schemaVersion) ||
    schemaVersion !== TWS_SUPPORTED_REPORT_SCHEMA_VERSION
  ) {
    return yield* new TwsUnsupportedSchemaVersionError({
      command,
      actualVersion: schemaVersion,
      supportedVersion: TWS_SUPPORTED_REPORT_SCHEMA_VERSION,
    });
  }
  return raw;
});

export function decodeTwsStatus(
  output: string,
): Effect.Effect<TwsStatusReport, TwsOutputDecodeError | TwsUnsupportedSchemaVersionError> {
  return decodeVersionedReport("status", output, STATUS_REQUIRED_KEYS).pipe(
    Effect.flatMap((raw) =>
      Effect.all({
        workspace: rawObject("status", raw.workspace, "workspace must be an object"),
        summary: rawObject("status", raw.summary, "summary must be an object"),
      }).pipe(
        Effect.flatMap(({ workspace, summary }) => {
          if (
            typeof raw.generated_at !== "string" ||
            !Array.isArray(raw.features) ||
            !Array.isArray(raw.issues)
          ) {
            return Effect.fail(
              outputDecodeError("status", "invalid-shape", "status report fields are invalid"),
            );
          }
          const unknownEnums = observeUnknownEnums(raw);
          const summaryNeedsAttention =
            typeof summary.needs_attention === "number" && summary.needs_attention > 0;
          return Effect.succeed({
            schemaVersion: 1 as const,
            generatedAt: raw.generated_at,
            workspace,
            features: raw.features,
            issues: raw.issues,
            summary,
            raw,
            unknownEnums,
            decoderDegraded: unknownEnums.length > 0,
            twsNeedsAttention: summaryNeedsAttention || hasTwsAttention(raw),
          });
        }),
      ),
    ),
  );
}

export function decodeTwsStackStatus(
  output: string,
): Effect.Effect<TwsStackStatusReport, TwsOutputDecodeError | TwsUnsupportedSchemaVersionError> {
  return decodeVersionedReport("stack-status", output, STACK_REQUIRED_KEYS).pipe(
    Effect.flatMap((raw) =>
      Effect.all({
        workspace: rawObject("stack-status", raw.workspace, "workspace must be an object"),
        summary: rawObject("stack-status", raw.summary, "summary must be an object"),
      }).pipe(
        Effect.flatMap(({ workspace, summary }) => {
          if (typeof raw.feature !== "string" || !Array.isArray(raw.entries)) {
            return Effect.fail(
              outputDecodeError(
                "stack-status",
                "invalid-shape",
                "stack status report fields are invalid",
              ),
            );
          }
          const unknownEnums = observeUnknownEnums(raw);
          return Effect.succeed({
            schemaVersion: 1 as const,
            workspace,
            feature: raw.feature,
            entries: raw.entries,
            summary,
            raw,
            unknownEnums,
            decoderDegraded: unknownEnums.length > 0,
            twsNeedsAttention: hasTwsAttention(raw),
          });
        }),
      ),
    ),
  );
}
